import { Suspense, cache } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

const getDashboardData = cache(async () => {
  const res = await fetch('https://api.example.com/dashboard', { cache: 'no-store' })
  if (!res.ok) throw new Error('Failed to load dashboard data')
  return res.json()
})

async function CardStatsSection() {
  const data = await getDashboardData()
  return (
    <CardStats totalRevenue={data.totalRevenue} totalInvoices={data.totalInvoices} />
  )
}

async function RevenueChartSection() {
  const data = await getDashboardData()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesSection() {
  const data = await getDashboardData()
  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsFallback() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton" aria-hidden="true">
        <h2>Total Revenue</h2>
        <p>&nbsp;</p>
      </div>
      <div className="card skeleton" aria-hidden="true">
        <h2>Total Invoices</h2>
        <p>&nbsp;</p>
      </div>
    </div>
  )
}

function RevenueChartFallback() {
  return (
    <div className="chart skeleton" aria-hidden="true">
      <h2>Revenue</h2>
      <ul>
        {Array.from({ length: 6 }).map((_, i) => (
          <li key={i}>
            <p>&nbsp;</p>
          </li>
        ))}
      </ul>
    </div>
  )
}

function LatestInvoicesFallback() {
  return (
    <div className="invoices skeleton" aria-hidden="true">
      <h2>Latest Invoices</h2>
      <ul>
        {Array.from({ length: 5 }).map((_, i) => (
          <li key={i}>
            <p>&nbsp;</p>
          </li>
        ))}
      </ul>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsSection />
      </Suspense>
      <Suspense fallback={<RevenueChartFallback />}>
        <RevenueChartSection />
      </Suspense>
      <Suspense fallback={<LatestInvoicesFallback />}>
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}
